function parseCsv(text) {
    const rows = [];
    let row = [], field = '', quoted = false;
    for (let i = 0; i < text.length; i++) {
        const c = text[i];
        if (quoted) {
            if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
            else if (c === '"') quoted = false;
            else field += c;
        } else if (c === '"') quoted = true;
        else if (c === ',') { row.push(field); field = ''; }
        else if (c === '\r' || c === '\n') {
            if (c === '\r' && text[i + 1] === '\n') i++;
            row.push(field); field = '';
            if (row.some((v) => v !== '')) rows.push(row);
            row = [];
        } else field += c;
    }
    if (field !== '' || row.length) { row.push(field); if (row.some((v) => v !== '')) rows.push(row); }
    const out = [];
    let header = null;
    for (const r of rows) {
        if (r[1] === 'result' && r[2] === 'table') { header = r; continue; }
        if (header) out.push(Object.fromEntries(header.map((h, i) => [h, r[i]])));
    }
    return out;
}
// Line protocol escaping
const tag = (v) => String(v).replace(/[\\, =]/g, (c) => '\\' + c);
const str = (v) => '"' + String(v).replace(/[\\"]/g, (c) => '\\' + c) + '"';
const esc = (v) => String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (t) => (t === null || t === undefined || Number.isNaN(t) ? '–' : (Math.round(t * 10) / 10).toFixed(1) + ' °C');
const minutes = (ms) => Math.max(0, Math.round(ms / 60000));
const label = (u) => (u.name || u.id) + (u.location ? ' (' + u.location + ')' : '');
// A time as people read it, in the project's timezone (TZ)
const when = (t) => DateTime.fromMillis(typeof t === 'number' ? t : Date.parse(t), { zone: setting('GENERIC_TIMEZONE', 'UTC') })
    .toFormat('yyyy-MM-dd HH:mm ZZZZ');
// The ack link carries a signature, so only links from an alert work
const crypto = require('crypto');
const sign = (device, excursion) => crypto.createHmac('sha256', setting('ACK_SECRET', ''))
    .update(device + '|' + excursion).digest('hex').slice(0, 32);

// Daily cold-chain record: per unit, the range of temperatures, the minutes
// out of range or without data, and every excursion with who acknowledged it
// and the corrective action. Attached as CSV (hourly log) and saved to
// ai/data/reports/ with an HTML copy.
const p = $('Period').first().json;
const units = $('Parse units').first().json.units;
const start = Date.parse(p.start), stop = Date.parse(p.stop);
const zone = p.zone;
const local = (t) => DateTime.fromMillis(t, { zone }).toFormat('yyyy-MM-dd HH:mm');

// 1-minute windows: { device: [{t, min, max, mean}] }
const windows = {};
for (const r of parseCsv($('Query readings').first().json.data || '')) {
    (windows[r.device] = windows[r.device] || []).push({ t: Date.parse(r._time), min: Number(r.min), max: Number(r.max), mean: Number(r.mean) });
}
// Excursions overlapping the day
const byEx = {};
for (const r of parseCsv($('Query events').first().json.data || '')) {
    const key = r.device + '|' + r.excursion;
    const e = (byEx[key] = byEx[key] || { device: r.device, id: r.excursion, start: Date.parse(r.excursion), events: {} });
    e.events[r.type] = { time: Date.parse(r._time), message: r.message, temperature: r.temperature, by: r.by, action: r.action };
}
const excursions = Object.values(byEx).filter((e) => e.start < stop && (!e.events.resolve || e.events.resolve.time >= start));

const expected = Math.max(0, Math.round((stop - start) / 60000));
const units_ = units.map((u) => {
    const w = windows[u.id] || [];
    const out = w.filter((x) => x.max > u.max || x.min < u.min).length;
    const ex = excursions.filter((e) => e.device === u.id).sort((a, b) => a.start - b.start);
    const open = ex.filter((e) => !e.events.ack);
    return {
        id: u.id, name: u.name || u.id, location: u.location || '', min_limit: u.min, max_limit: u.max,
        min: w.length ? Math.min(...w.map((x) => x.min)) : null,
        max: w.length ? Math.max(...w.map((x) => x.max)) : null,
        mean: w.length ? w.reduce((s, x) => s + x.mean, 0) / w.length : null,
        minutes_out_of_range: out,
        minutes_without_data: Math.max(0, expected - w.length),
        status: open.length ? 'ACTION NEEDED' : ex.length || out ? 'EXCURSION, ACTIONED' : 'OK',
        excursions: ex.map((e) => ({
            start: new Date(e.start).toISOString(),
            end: e.events.resolve ? new Date(e.events.resolve.time).toISOString() : null,
            minutes: minutes((e.events.resolve ? e.events.resolve.time : Date.now()) - e.start),
            cause: e.events.start ? e.events.start.message : '',
            alerted: !!e.events.alert, escalated: !!e.events.escalate,
            acknowledged_by: e.events.ack ? e.events.ack.by : null,
            corrective_action: e.events.ack ? e.events.ack.action : null,
        })),
    };
});

// Hourly log (CSV)
const csvCell = (v) => (v === null || v === undefined ? '' : /[",\n]/.test(String(v)) ? '"' + String(v).replace(/"/g, '""') + '"' : String(v));
const round = (v) => (v === null || v === undefined || Number.isNaN(v) ? null : Math.round(v * 10) / 10);
const csv = [['unit', 'name', 'hour', 'min_c', 'max_c', 'mean_c', 'minutes_out_of_range', 'limit_min_c', 'limit_max_c']];
for (const u of units) {
    const hours = {};
    for (const x of windows[u.id] || []) {
        const h = DateTime.fromMillis(x.t - 1, { zone }).startOf('hour').toFormat('yyyy-MM-dd HH:00');
        const s = (hours[h] = hours[h] || { min: Infinity, max: -Infinity, sum: 0, n: 0, out: 0 });
        s.min = Math.min(s.min, x.min); s.max = Math.max(s.max, x.max); s.sum += x.mean; s.n++;
        if (x.max > u.max || x.min < u.min) s.out++;
    }
    for (const [h, s] of Object.entries(hours).sort()) {
        csv.push([u.id, u.name || u.id, h, round(s.min), round(s.max), round(s.sum / s.n), s.out, u.min, u.max]);
    }
}
const csvText = csv.map((r) => r.map(csvCell).join(',')).join('\n') + '\n';

// Email and HTML copy
const attention = units_.filter((u) => u.status === 'ACTION NEEDED').length;
const subject = '[Cold chain] Daily record ' + p.date + (attention ? ': ' + attention + ' unit(s) need corrective action' : ': all units OK');
const color = { 'OK': '#15803d', 'EXCURSION, ACTIONED': '#b45309', 'ACTION NEEDED': '#b91c1c' };
const td = (v) => '<td>' + esc(v === null || v === undefined ? '–' : v) + '</td>';
let html = '<!doctype html><html><head><meta charset="utf-8"><title>' + esc(subject) + '</title></head>'
    + '<body style="font-family:system-ui,sans-serif"><h2>Cold-chain record, ' + esc(p.date) + ' (' + esc(zone) + ')</h2>'
    + '<table cellpadding="6" style="border-collapse:collapse" border="1"><tr><th>Unit</th><th>Limits</th><th>Min</th><th>Max</th><th>Mean</th>'
    + '<th>Min out of range</th><th>Min without data</th><th>Status</th></tr>';
for (const u of units_) {
    html += '<tr>' + td(u.name + (u.location ? ' (' + u.location + ')' : '')) + td(u.min_limit + '–' + u.max_limit + ' °C')
        + td(fmt(u.min)) + td(fmt(u.max)) + td(fmt(u.mean)) + td(u.minutes_out_of_range) + td(u.minutes_without_data)
        + '<td style="color:' + color[u.status] + ';font-weight:600">' + esc(u.status) + '</td></tr>';
}
html += '</table>';
const all = units_.flatMap((u) => u.excursions.map((e) => ({ unit: u.name, ...e })));
if (all.length) {
    html += '<h3>Excursions</h3><table cellpadding="6" style="border-collapse:collapse" border="1"><tr><th>Unit</th><th>Start</th>'
        + '<th>End</th><th>Minutes</th><th>Cause</th><th>Escalated</th><th>Acknowledged by</th><th>Corrective action</th></tr>';
    for (const e of all) {
        html += '<tr>' + td(e.unit) + td(local(Date.parse(e.start))) + td(e.end ? local(Date.parse(e.end)) : 'ongoing')
            + td(e.minutes) + td(e.cause) + td(e.escalated ? 'yes' : 'no') + td(e.acknowledged_by || 'NOT ACKNOWLEDGED') + td(e.corrective_action) + '</tr>';
    }
    html += '</table>';
}
html += '<p style="color:#666">Hourly log attached as CSV. Generated ' + esc(DateTime.now().setZone(zone).toISO()) + '.</p></body></html>';

const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const name = 'coldchain-' + p.date;
return [{
    json: { date: p.date, subject, html, attention, units: units_, files: [name + '.csv', name + '.html'] },
    binary: {
        csv: { data: b64(csvText), mimeType: 'text/csv', fileName: name + '.csv' },
        html: { data: b64(html), mimeType: 'text/html', fileName: name + '.html' },
    },
}];

// The webhook's response
const r = $('Build report').first().json;
return [{ json: { date: r.date, subject: r.subject, attention: r.attention, files: r.files, units: r.units } }];
